"""Generateur pro-commerce-mat-part-C.json — lot C : pratique et environnement (20 fiches).

Pratique professionnelle (8), Français professionnel (4), Langues (4), Développement durable (4).
Chaque fiche : 12 points, 9 questions corrigees (7 QCM + 2 texte), 7 blocs ordonnes, 3 SVG.
Annees utilisees : 2nde pro, 1re pro, Terminale pro (identiques aux lots A et B).
"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _pro_commerce_common import S, R, QC, QT, C, build, valider_et_ecrire

F = []


def add(prefix, titre, mat, ans, points, questions, c):
    F.append(build(prefix, titre, mat, ans, points, questions, c))


